ALTER TABLE pricing_quotes ADD CONSTRAINT quote_org_property UNIQUE(organization_id,property_id,id),ADD CONSTRAINT quote_org_property_room UNIQUE(organization_id,property_id,room_id,id);ALTER TABLE bookings ADD CONSTRAINT booking_org_property UNIQUE(organization_id,property_id,id),ADD CONSTRAINT booking_quote_scoped FOREIGN KEY(organization_id,property_id,room_id,quote_id) REFERENCES pricing_quotes(organization_id,property_id,room_id,id);ALTER TABLE booking_consents ADD CONSTRAINT consent_booking_scoped FOREIGN KEY(organization_id,property_id,booking_id) REFERENCES bookings(organization_id,property_id,id),ADD CONSTRAINT consent_quote_scoped FOREIGN KEY(organization_id,property_id,quote_id) REFERENCES pricing_quotes(organization_id,property_id,id);ALTER TABLE booking_events_outbox ADD CONSTRAINT outbox_booking_scoped FOREIGN KEY(organization_id,property_id,booking_id) REFERENCES bookings(organization_id,property_id,id);ALTER TABLE invoices ADD COLUMN bill_to jsonb NOT NULL DEFAULT '{}';ALTER TABLE invoices ALTER COLUMN bill_to DROP DEFAULT;
CREATE FUNCTION guard_invoice_source() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NOT EXISTS(SELECT FROM bookings b WHERE b.id=NEW.booking_id AND b.organization_id=NEW.organization_id AND b.property_id=NEW.property_id AND b.customer_id=NEW.customer_id AND b.state IN('held','confirmed') AND b.pricing_snapshot=NEW.pricing_snapshot) THEN RAISE EXCEPTION 'INVALID_STATE' USING ERRCODE='P0409';END IF;RETURN NEW;END $$;CREATE TRIGGER invoice_source_guard BEFORE INSERT ON invoices FOR EACH ROW EXECUTE FUNCTION guard_invoice_source();
CREATE OR REPLACE FUNCTION reserve_booking_allocation(org uuid,bid uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE b public.bookings%ROWTYPE;r public.rooms%ROWTYPE;aid uuid;BEGIN SELECT * INTO b FROM public.bookings WHERE organization_id=org AND id=bid AND origin='staff';IF NOT FOUND OR NOT public.can_manage_inventory(org,b.property_id) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0404';END IF;PERFORM public.assert_entitlement_quota(org,0,0,0);PERFORM pg_advisory_xact_lock(hashtextextended('inventory-location:'||org::text||':'||b.property_id::text,0));SELECT * INTO r FROM public.rooms WHERE id=b.room_id AND organization_id=org FOR UPDATE;SELECT * INTO b FROM public.bookings WHERE id=bid AND organization_id=org FOR UPDATE;IF b.state NOT IN('held','confirmed') OR r.condition<>'ready' OR r.archived_at IS NOT NULL OR b.occupant_count>r.capacity OR NOT EXISTS(SELECT FROM public.room_checklists c WHERE c.room_id=r.id AND c.water AND c.electric AND c.lock AND c.furniture AND c.clean AND c.recorded_at IS NOT NULL) OR EXISTS(SELECT FROM public.work_orders w WHERE w.room_id=r.id AND w.state='open' AND w.blocking) OR EXISTS(SELECT FROM public.room_presence WHERE room_id=r.id AND exited_at IS NULL) THEN RAISE EXCEPTION 'INVALID_STATE' USING ERRCODE='P0409';END IF;INSERT INTO public.room_allocations(organization_id,property_id,room_id,kind,starts_on,ends_on,booking_id)VALUES(org,b.property_id,b.room_id,CASE WHEN b.state='held' THEN 'hold' ELSE 'stay' END,b.starts_on,b.ends_on,b.id) RETURNING id INTO aid;RETURN aid;END $$;REVOKE ALL ON FUNCTION reserve_booking_allocation(uuid,uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION reserve_booking_allocation(uuid,uuid) TO kost_app;
